const http=require('node:http'),fs=require('node:fs'),path=require('node:path');const root=path.join(__dirname,'public');const read=p=>JSON.parse(fs.readFileSync(path.join(root,p),'utf8'));const idx=read('archive-index.json'),app=fs.readFileSync(path.join(root,'app-v101.js'),'utf8');const local=JSON.parse(app.match(/,tracks=(\{[\s\S]*?\});const normal=/)[1]),books=JSON.parse(app.match(/,books=(\[[\s\S]*?\]),novels=/)[1]),novels=JSON.parse(app.match(/,novels=(\[[\s\S]*?\]),tracks=/)[1]);const audio=read('audio-archive.json');for(const b of audio.books)local[b.id]=b.tracks.map(t=>({...t,url:t.url||t.originUrl}));const normal=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const cache=new Map();function unpack(s){const b=Buffer.from(s,'base64'),o=[];for(let i=0;i<b.length;){const n=b[i++];if(n<128){for(let j=0;j<=n;j++)o.push(b[i++]);}else{const off=(b[i++]<<8)|b[i++];if(off<1||off>o.length)throw Error('Invalid archive');for(let j=0;j<n-128+4;j++)o.push(o[o.length-off]);}}return JSON.parse(Buffer.from(o).toString('utf8'))}
function episodes(id){if(cache.has(id))return cache.get(id);const s=idx.sources.find(s=>s.id===id);if(!s)return [];let rows=[];for(const p of s.parts){const d=read(p.slice(1));rows.push(...(d.rows||unpack(d.packed)));}const items=rows.map(r=>({id:r[0],title:r[1],date:r[2],year:r[3],url:r[4],source:r[5],desc:r[6],kind:'podcast'}));cache.set(id,items);return items}
