async function librivox(q,id,offset){let u=new URL('https://librivox.org/api/feed/audiobooks/');u.searchParams.set('format','json');u.searchParams.set('extended','1');if(id)u.searchParams.set('id',id);else{u.searchParams.set('language','French');u.searchParams.set('limit','50');u.searchParams.set('offset',String(offset));if(q)u.searchParams.set('title','^'+q)}let d=await fetchJSON(u);return parseLibriBooks(d.books||[])}
function parseLibriBooks(rows){return rows.flatMap(b=>{let count=Number(b.num_sections),tracks=(b.sections||[]).map((s,i)=>({title:s.title||'Chapitre '+(i+1),url:String(s.listen_url||'').replace(/^http:/,'https:')}));let author=(b.authors||[]).map(a=>[a.first_name,a.last_name].filter(Boolean).join(' ')).join(', ');let text=(b.title||'')+' '+(b.description||'').replace(/<[^>]*>/g,' ');if(b.language!=='French'||!b.url_text_source||!b.authors?.length||!b.authors.every(a=>Number(a.dod)>0&&Number(a.dod)<=1955)||!(b.translators||[]).every(a=>Number(a.dod)>0&&Number(a.dod)<=1955)||!/(?:int[ée]gral|unabridged|non abr[ée]g[ée])/i.test(text)||/\b(?:adaptation|extraits?|r[ée]sum[ée]s?)\b/i.test(text)||!count||tracks.length!==count||!tracks.every(t=>/^https:\/\/(?:[^/]+\.)?archive\.org\//i.test(t.url))||!b.url_zip_file)return [];return [{id:'lv'+b.id,bookId:String(b.id),title:b.title,author,kind:'audio',source:b.url_librivox,download:b.url_zip_file,count,desc:'Intégrale indiquée par la source · '+count+' pistes · LibriVox',tracks}];})}


