async function archiveAudioIndex(){const query=new URL('https://archive.org/advancedsearch.php');query.searchParams.set('q','collection:librivoxaudio AND (language:fre OR language:fra OR language:French) AND (description:unabridged OR description:intégral OR description:intégrale)');for(const f of ['identifier','title','creator','description','language'])query.searchParams.append('fl[]',f);query.searchParams.set('rows','150');query.searchParams.set('output','json');const data=await fetchJSON(query);const docs=(data.response?.docs||[]).filter(d=>/^[\w.-]+$/.test(d.identifier||''));const authors=/^(?:verne|hugo|dumas|zola|balzac|maupassant|flaubert|stendhal|sand|leblanc|leroux|perrault|pergaud|moliere|racine|corneille|daudet|gautier|baudelaire|proust|gaboriau|sue|malot|mirbeau|loti|renard|rostand|maupassant|france|segur)\s*,/i;
const candidates=docs.filter(d=>{const creator=Array.isArray(d.creator)?d.creator:[d.creator];return creator.length&&creator.every(x=>authors.test(normal(x))||/^(?:jules verne|victor hugo|alexandre dumas|emile zola|honore de balzac|guy de maupassant|gustave flaubert|gaston leroux|maurice leblanc|alphonse daudet|theophile gautier|emile gaboriau|eugene sue|hector malot|marcel proust)(?:\s*\([^)]*\))?$/i.test(normal(x)))}).slice(0,60);let out=[];for(let i=0;i<candidates.length;i+=5){const batch=await Promise.allSettled(candidates.slice(i,i+5).map(async d=>{const meta=await fetchJSON('https://archive.org/metadata/'+d.identifier);const m=meta.metadata||{},text=String(m.description||'').replace(/<[^>]+>/g,' '),langs=[m.language].flat();if(!langs.some(l=>/^(fre|fra|french|fr)$/i.test(l))||!/(?:int[ée]gral|unabridged|non abr[ée]g[ée])/i.test(text)||/\b(?:abridged|extraits?|r[ée]sum[ée]s?|adaptation)\b/i.test(text.replace(/unabridged/ig,''))||/\b(?:translated by|traduit par|traduction de)\b/i.test(text))return null;const files=meta.files||[];const group=files.filter(f=>f.format==='64Kbps MP3'&&/\.mp3$/i.test(f.name)&&Number(f.size)>0);const originals=files.filter(f=>f.source==='original'&&/\.mp3$/i.test(f.name)&&Number(f.size)>0);if(!group.length||!originals.length||group.length!==originals.length)return null;const tracks=group.sort((a,b)=>a.name.localeCompare(b.name,'en',{numeric:true})).map((f,j)=>({title:f.title||'Piste '+(j+1),url:'https://archive.org/download/'+d.identifier+'/'+encodeURIComponent(f.name),bytes:Number(f.size)}));const source='https://archive.org/details/'+d.identifier;return {id:'ia:'+d.identifier,bookId:'ia:'+d.identifier,title:String(m.title||d.title),author:[m.creator||d.creator].flat().join(' · '),kind:'audio',source,download:source,image:'https://archive.org/services/img/'+d.identifier,count:tracks.length,desc:'Intégrale annoncée · inventaire MP3 concordant · LibriVox / Internet Archive',tracks}}));out.push(...batch.flatMap(x=>x.status==='fulfilled'&&x.value?[x.value]:[]))}console.log('IA_AUDIO_INDEX',JSON.stringify({candidates:candidates.length,found:out.length,tracks:out.reduce((n,b)=>n+b.tracks.length,0)}));return out}

async function buildAudioIndex(){if(audioIndex.length)return audioIndex;if(audioIndexPending)return audioIndexPending;audioIndexPending=(async()=>{const collected=[];let scanned=0,successful=0;const offsets=Array.from({length:20},(_,i)=>i*50);for(let i=0;i<offsets.length;i+=4){const group=await Promise.allSettled(offsets.slice(i,i+4).map(async offset=>{const u=new URL('https://librivox.org/api/feed/audiobooks/');u.search=new URLSearchParams({format:'json',extended:'1',language:'French',limit:'50',offset:String(offset)}).toString();const d=await fetchJSON(u);if(!Array.isArray(d.books))throw Error('No books array');return d.books}));for(const result of group)if(result.status==='fulfilled'){successful++;scanned+=result.value.length;collected.push(...parseLibriBooks(result.value))}if(i===0&&successful===0)break;if(group.every(r=>r.status==='fulfilled'&&r.value.length<50))break}if(collected.length<30)try{collected.push(...await archiveAudioIndex())}catch(e){console.log('IA_AUDIO_UNAVAILABLE',String(e))}audioIndex=[...new Map(collected.map(b=>[b.bookId,b])).values()];if(audioIndex.length)try{fs.writeFileSync(audioIndexPath,JSON.stringify({items:audioIndex,scanned,generatedAt:new Date().toISOString(),source:'LibriVox API'}))}catch{}console.log('AUDIO_BULK_INDEX',JSON.stringify({scanned,successful,admitted:audioIndex.length,tracks:audioIndex.reduce((n,b)=>n+b.tracks.length,0)}));return audioIndex})().finally(()=>{audioIndexPending=null});return audioIndexPending}

