function xmlText(s){return String(s||'').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/<[^>]+>/g,' ').replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos|nbsp);/gi,(m,c)=>{const a={amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:' '};if(a[c])return a[c];try{let n=c[1].toLowerCase()==='x'?parseInt(c.slice(2),16):parseInt(c.slice(1),10);return String.fromCodePoint(n)}catch{return m}}).replace(/\s+/g,' ').trim()}
function xmlTag(s,tag){return xmlText(s.match(new RegExp('<'+tag+'(?:\\s[^>]*)?>([\\s\\S]*?)<\\/'+tag+'\\s*>','i'))?.[1])}
function xmlAttr(s,key){return xmlText(s.match(new RegExp('\\b'+key+'\\s*=\\s*(?:"([^"]*)"|\\x27([^\\x27]*)\\x27)','i'))?.slice(1).find(v=>v!==undefined))}
function parseRSS(xml,id){let out=[];for(const match of xml.matchAll(/<item(?:\s[^>]*)?>([\s\S]*?)<\/item\s*>/gi)){const v=match[1],enclosures=[...v.matchAll(/<enclosure\b[^>]*>/gi)].map(m=>m[0]);const enc=enclosures.find(e=>/^audio\//i.test(xmlAttr(e,'type'))||/\.(?:mp3|m4a|aac|ogg)(?:[?#]|$)/i.test(xmlAttr(e,'url')));if(!enc)continue;let url=xmlAttr(enc,'url'),title=xmlTag(v,'title'),raw=xmlTag(v,'pubDate'),date=Date.parse(raw);if(!/^https?:\/\//i.test(url)||!title||!Number.isFinite(date))continue;const stamp=new Date(date).toISOString();out.push({id:id+':'+(xmlTag(v,'guid')||url),title,date:stamp,year:stamp.slice(0,4),url,source:xmlTag(v,'link'),desc:xmlTag(v,'description').slice(0,800),kind:'podcast'})}return [...new Map(out.map(x=>[x.url,x])).values()]}
function mergedEpisodes(a,b){const rows=[],byURL=new Map(),byIdentity=new Map();for(const x of [...a,...b]){if(!x?.url)continue;const stamp=Date.parse(x.date||'');const title=normal(x.title).replace(/[^\p{L}\p{N}]+/gu,' ').trim();const key=title&&Number.isFinite(stamp)&&stamp>0?title+'|'+Math.floor(stamp/60000):'';const pos=byURL.get(x.url)??(key?byIdentity.get(key):undefined);if(pos!==undefined){const prev=rows[pos];rows[pos]={...prev,...x,id:prev.id};byURL.set(x.url,pos);if(key)byIdentity.set(key,pos)}else{const n=rows.length;rows.push(x);byURL.set(x.url,n);if(key)byIdentity.set(key,n)}}return rows.sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
async function liveEpisodes(id){const seed=rssMap.get(id),historical=mergedEpisodes(episodes(id),delta[id]||[]);if(!seed)return {items:historical,archived:true,live:false};const old=liveCache.get(id);if(old&&Date.now()-old.time<600000)return {items:mergedEpisodes(historical,old.items),archived:true,live:true};if(liveInflight.has(id))return liveInflight.get(id);const p=(async()=>{try{const r=await fetch(seed.url,{signal:AbortSignal.timeout(8500),headers:{accept:'application/rss+xml, application/xml, text/xml, */*'}});if(!r.ok)throw Error('HTTP '+r.status);const xml=await r.text();const fresh=parseRSS(xml,id);if(!fresh.length)throw Error('Flux vide');const items=mergedEpisodes(old?.items||[],fresh);liveCache.set(id,{time:Date.now(),items});return {items:mergedEpisodes(historical,items),archived:true,live:true,newCount:Math.max(0,mergedEpisodes(historical,items).length-historical.length)}}catch{return {items:mergedEpisodes(historical,old?.items||[]),archived:true,live:false}}})();liveInflight.set(id,p);try{return await p}finally{liveInflight.delete(id)}}
