function csvRows(csv){let result=[],row=[],field='',quoted=false;for(let i=0;i<csv.length;i++){const c=csv[i];if(quoted){if(c==='"'&&csv[i+1]==='"'){field+='"';i++}else if(c==='"')quoted=false;else field+=c}else if(c==='"'&&!field)quoted=true;else if(c===','){row.push(field);field=''}else if(c==='\n'){row.push(field.replace(/\r$/,''));result.push(row);row=[];field=''}else field+=c}if(field||row.length){row.push(field.replace(/\r$/,''));result.push(row)}return result}
const frenchWriters=/^(?:verne|hugo|dumas|maquet|zola|balzac|maupassant|flaubert|stendhal|sand|leb[l]?anc|leroux|perrault|pergaud|moli[eè]re|racine|corneille|lafontaine|la fontaine|voltaire|rousseau|diderot|montesquieu|chateaubriand|daudet|gautier|baudelaire|verlaine|rimbaud|mallarm[eé]|musset|lamartine|nerval|m[eé]rim[eé]e|anatole france|france|proust|rolland|barbey d'aurevilly|huysmans|mirbeau|loti|malot|s[eé]gur|colette|renard|rostand|marivaux|beaumarchais|beaugrand|gaboriau|ponson du terrail|feuillet|sue|f[eé]val|sandeau|l[eé]on bloy|bloy|vall[eé]s|vigny|p[eé]guy|apollinaire|goncourt|michelet|renan|ta ine|taine|du camp|louis|lou[yÿ]s|alain-fournier|descartes|pascal|rabelais|montaigne|la rochefoucauld|la bruy[eè]re|vauvenargues|b[eé]ranger|ch[eé]nier|g[eé]raldy|t[oö]pffer),/i;
function bulkParse(csv){const rows=csvRows(csv.replace(/^\uFEFF/,'')),h=rows.shift()||[];const col=n=>h.findIndex(x=>x.trim().toLowerCase()===n.toLowerCase());const [id,type,title,lang,author,subject,shelf]=['Text#','Type','Title','Language','Authors','Subjects','Bookshelves'].map(col);if([id,type,title,lang,author].some(x=>x<0))throw Error('CSV schema');const books=[];for(const r of rows){if(!/^\d+$/.test(r[id]||'')||r[type]!=='Text'||r[lang]?.trim()!=='fr'||!r[title]||!r[author])continue;const creators=r[author].split(';').map(x=>x.trim());if(!creators.every(a=>{const match=a.match(/(?:\d{3,4})\s*-\s*(\d{3,4})\s*$/);return frenchWriters.test(a)&&match&&Number(match[1])<=1955}))continue;const tags=normal((r[subject]||'')+' '+(r[shelf]||''));const category=/juvenile|children|enfant|jeunesse/.test(tags)?'Jeunesse':/poetry|poesie|poemes/.test(tags)?'Poésie':/drama|theatre|plays/.test(tags)?'Théâtre':/fiction|romans|novels|adventure|short stories/.test(tags)?'Romans':/history|histoire/.test(tags)?'Histoire':'Autres';const n=r[id],source='https://www.gutenberg.org/ebooks/'+n;books.push({id:'g'+n,read:n,title:r[title],author:creators.join(' · '),kind:'book',category,source,download:source+'.epub3.images',image:'https://www.gutenberg.org/cache/epub/'+n+'/pg'+n+'.cover.medium.jpg',desc:'Notice Gutenberg · édition française · disponibilité et droits de cette édition à vérifier',subjects:r[subject]||''})}if(books.length<100)throw Error('Catalogue incomplet : '+books.length);return books}

const snapshotBase='https://raw.githubusercontent.com/rfordatascience/tidytuesday/main/data/2025/2025-06-03/';
async function fetchCSV(url){const res=await fetch(url,{signal:AbortSignal.timeout(22000)});if(!res.ok)throw Error('HTTP '+res.status);let bytes=Buffer.from(await res.arrayBuffer());if(bytes.length>45000000)throw Error('CSV too large');if(bytes[0]===31&&bytes[1]===139)bytes=require('node:zlib').gunzipSync(bytes,{maxOutputLength:45000000});return new TextDecoder().decode(bytes)}
function csvTable(data){const rows=csvRows(data.replace(/^\uFEFF/,'')),headers=rows.shift()||[];const index=Object.fromEntries(headers.map((h,i)=>[h.trim().toLowerCase(),i]));return {rows,index}}
async function bulkSnapshot(){const [md,ad]=await Promise.all([fetchCSV(snapshotBase+'gutenberg_metadata.csv'),fetchCSV(snapshotBase+'gutenberg_authors.csv')]);const m=csvTable(md),a=csvTable(ad);for(const key of ['gutenberg_id','title','author','gutenberg_author_id','language','rights','has_text'])if(!(key in m.index))throw Error('Missing metadata '+key);for(const key of ['gutenberg_author_id','deathdate'])if(!(key in a.index))throw Error('Missing author '+key);const dates=new Map(a.rows.map(row=>[row[a.index.gutenberg_author_id],row[a.index.deathdate]]));const items=[];for(const row of m.rows){const get=k=>row[m.index[k]]||'',id=get('gutenberg_id'),author=get('author'),death=Number(dates.get(get('gutenberg_author_id')));if(!/^\d+$/.test(id)||get('language')!=='fr'||get('rights')!=='Public domain in the USA.'||!/^true$/i.test(get('has_text'))||!death||death>1955||!frenchWriters.test(author)||!get('title'))continue;const tags=normal(get('gutenberg_bookshelf')+' '+get('title'));const category=/juvenile|children|enfant|jeunesse/.test(tags)?'Jeunesse':/poetry|poesie|poemes/.test(tags)?'Poésie':/drama|theatre|plays/.test(tags)?'Théâtre':/history|histoire/.test(tags)?'Histoire':'Romans';const source='https://www.gutenberg.org/ebooks/'+id;items.push({id:'g'+id,read:id,title:get('title'),author,kind:'book',category,source,download:source+'.epub3.images',image:'https://www.gutenberg.org/cache/epub/'+id+'/pg'+id+'.cover.medium.jpg',desc:'Notice issue de Gutenberg (instantané 2025) · texte signalé · édition et droits à vérifier'})}if(items.length<100)throw Error('Snapshot incomplete: '+items.length);return {items,source:snapshotBase+'gutenberg_metadata.csv'}}
async function bulkLoad(){if(bulkItems.length)return bulkItems;if(bulkPending)return bulkPending;if(Date.now()<bulkRetry)return [];bulkPending=(async()=>{const urls=['https://www.gutenberg.org/cache/epub/feeds/pg_catalog.csv.gz','https://gutenberg.pglaf.org/cache/epub/feeds/pg_catalog.csv.gz'];try{const d=await Promise.any([...urls.map(async url=>({items:bulkParse(await fetchCSV(url)),source:url})),bulkSnapshot()]);bulkItems=d.items;bulkSource=d.source;try{fs.writeFileSync(bulkPath,JSON.stringify({...d,generatedAt:new Date().toISOString()}))}catch{}console.log('BULK_FR_INDEX',bulkItems.length,bulkSource);return bulkItems}catch(e){bulkRetry=Date.now()+300000;console.log('BULK_FR_UNAVAILABLE',JSON.stringify(e.errors?.map(x=>String(x))||[String(e)]));return []}finally{bulkPending=null}})();return bulkPending}
function bulkPage(q,genre,page){const words=normal(q).split(/\s+/).filter(Boolean);const list=[...new Map([...bulkItems,...novels].map(x=>[x.id,x])).values()].filter(x=>(genre==='Tous'||x.category===genre)&&words.every(w=>normal(x.title+' '+x.author+' '+(x.subjects||'')).includes(w)));const size=30;return {items:list.slice((page-1)*size,page*size),count:list.length,next:page*size<list.length,source:bulkSource||'Gutenberg bulk index',referencesOnly:true}}

async function readCatalogue(q,genre,page){if(bulkItems.length)return bulkPage(q,genre,page);if(await bulkLoad().then(a=>a.length))return bulkPage(q,genre,page);const key=JSON.stringify([q,genre,page]);if(readCache.has(key))return readCache.get(key);let items=page===1?novels.filter(x=>(genre==='Tous'||x.category===genre)&&normal(x.title+' '+x.author).includes(normal(q))):[];const url=new URL('https://gutendex.com/books/');url.searchParams.set('languages','fr');url.searchParams.set('copyright','false');url.searchParams.set('author_year_end','1955');url.searchParams.set('page',String(page));if(q)url.searchParams.set('search',q);if(genres[genre])url.searchParams.set('topic',genres[genre]);try{const d=await fetchJSON(url);const remote=(d.results||[]).filter(b=>b.copyright===false&&b.languages?.includes('fr')&&b.authors?.length&&b.authors.every(a=>Number.isInteger(a.death_year)&&a.death_year<=1955)&&b.formats?.['application/epub+zip']&&Object.keys(b.formats).some(k=>k.startsWith('text/plain'))).map(b=>({id:'g'+b.id,read:String(b.id),title:b.title,author:b.authors.map(a=>a.name).join(' · '),kind:'book',category:genre==='Tous'?'Romans':genre,source:'https://www.gutenberg.org/ebooks/'+b.id,download:b.formats['application/epub+zip'],image:b.formats['image/jpeg'],desc:'Édition française · Project Gutenberg · texte et EPUB'}));items=[...new Map([...items,...remote].map(b=>[b.id,b])).values()];const r={items,next:!!d.next,count:d.count,source:'Gutendex',rights:'US public domain; French author death year <=1955, translation rights require additional review'};if(readCache.size>50)readCache.clear();readCache.set(key,r);return r}catch{return {items,next:false,source:'local',offline:true}}}
function dcFields(xml,name){return [...xml.matchAll(new RegExp('<dc:'+name+'(?:\\s[^>]*)?>([\\s\\S]*?)<\\/dc:'+name+'\\s*>','gi'))].map(m=>xmlText(m[1]))}
async function bdCatalogue(q,page){const term=String(q||'').replace(/["\\\x00-\x1f]/g,' ').slice(0,100);const u=new URL('https://gallica.bnf.fr/SRU');u.searchParams.set('operation','searchRetrieve');u.searchParams.set('version','1.2');u.searchParams.set('maximumRecords','24');u.searchParams.set('startRecord',String((page-1)*24+1));u.searchParams.set('query','dc.rights all "domaine public" and (dc.title all "Bécassine" or dc.subject all "bandes dessinées" or dc.title all "Pieds nickelés")'+(term?' and dc.title all "'+term+'"':''));const matches=bdSeed.filter(x=>normal(q).split(/\s+/).filter(Boolean).every(w=>normal(x.title+' '+x.author).includes(w)));const localRows=matches.slice((page-1)*24,page*24);if(matches.length)return {items:localRows,count:matches.length,next:page*24<matches.length,source:'Cité BD / Gallica',referencesOnly:true};try{const r=await fetch(u,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('SRU');const xml=await r.text();const count=Number(xml.match(/<(?:\w+:)?numberOfRecords>(\d+)</)?.[1]||0);let rows=[];for(const m of xml.matchAll(/<(?:\w+:)?recordData(?:\s[^>]*)?>([\s\S]*?)<\/(?:\w+:)?recordData>/gi)){const v=m[1],rights=dcFields(v,'rights'),title=dcFields(v,'title')[0],author=dcFields(v,'creator').join(' · '),ids=dcFields(v,'identifier');const ark=ids.map(x=>x.match(/(?:https?:\/\/gallica\.bnf\.fr\/)?ark:\/12148\/([a-z0-9]+)/i)?.[1]).find(Boolean);if(!title||!ark||!rights.some(x=>normal(x).includes('domaine public'))||rights.some(x=>/sous droits|prot[eé]g[eé]|droits r[eé]serv[eé]s/i.test(x)))continue;const source='https://gallica.bnf.fr/ark:/12148/'+ark;rows.push({id:'bd:'+ark,title,author,kind:'book',category:'BD',source,readUrl:source,download:source+'.pdf',image:source+'/f1.thumbnail',desc:'Source gallica.bnf.fr / Bibliothèque nationale de France · domaine public signalé'})}return {items:[...new Map([...localRows,...rows].map(x=>[x.id,x])).values()],count,next:page*24<count}}catch{return {items:localRows,count:localRows.length,next:false,offline:true}}}
async function probeAudio(url){const ctrl=new AbortController();const timeout=setTimeout(()=>ctrl.abort(),9000);try{const r=await fetch(url,{signal:ctrl.signal,headers:{Range:'bytes=0-65535'}});if(!r.ok)return {state:'http_'+r.status};const reader=r.body.getReader();let chunks=[],n=0;try{while(n<65536){const v=await reader.read();if(v.done)break;chunks.push(Buffer.from(v.value).subarray(0,65536-n));n+=chunks[chunks.length-1].length}}finally{await reader.cancel().catch(()=>{})}const b=Buffer.concat(chunks);let format=null;if(b.length>=10&&b.subarray(0,3).toString()==='ID3')format='mp3-id3';else if(b.length>=4&&b[0]===255&&(b[1]&224)===224)format='mpeg-audio';else if(b.subarray(0,4).toString()==='OggS')format='ogg';else if(b.subarray(4,8).toString()==='ftyp')format='mp4';else if(b.subarray(0,4).toString()==='fLaC')format='flac';else if(b.subarray(0,4).toString()==='RIFF'&&b.subarray(8,12).toString()==='WAVE')format='wav';return {state:format?'header_ok':'unrecognized',format,bytes:b.length,status:r.status}}catch(e){return {state:'unreachable',error:e.name}}finally{clearTimeout(timeout)}}
async function auditExpansion(){const [r,b]=await Promise.all([readCatalogue('','Tous',1),bdCatalogue('',1)]);console.log('READ_AUDIT',JSON.stringify({romans:r.items.length,source:r.source,bd:b.items.length,notices:b.count,bdCatalogueTotal:bdSeed.length,offline:!!b.offline}));const reports=[];const found=await Promise.allSettled(archiveBooks.map(archiveEdition));const targets=[...Object.entries(local).map(([id,t])=>({id,url:t[0]?.url})),...found.flatMap(x=>x.status==='fulfilled'?[{id:x.value.bookId,url:x.value.tracks[0]?.url}]:[])];for(const id of ['m','a','first','h']){const x=await liveEpisodes(id);const history=new Set([...episodes(id),...(delta[id]||[])].map(x=>x.url));const fresh=x.items.filter(x=>!history.has(x.url));for(const item of fresh.slice(0,25))console.log('DELTA_ROW '+JSON.stringify({show:id,item:{...item,desc:item.desc?.slice(0,200)}}));if(x.items[0])targets.push({id:'podcast:'+id,url:x.items[0].url})}for(let i=0;i<targets.length;i+=4){const rs=await Promise.all(targets.slice(i,i+4).filter(x=>x.url).map(async t=>({id:t.id,...await probeAudio(t.url)})));reports.push(...rs);for(const r of rs)console.log('MEDIA_AUDIT '+JSON.stringify(r))}console.log('MEDIA_TOTAL',reports.length,reports.filter(x=>x.state==='header_ok').length);console.log('DELTA_SAVED',Object.values(delta).reduce((n,a)=>n+a.length,0));}

const textCache=new Map();
async function api(u,res){const q=u.searchParams.get('q')||'',id=u.searchParams.get('id'),offset=Math.max(0,Number(u.searchParams.get('offset'))||0);if(u.pathname==='/api/episodes'||u.pathname==='/api/extra'||u.pathname==='/api/chroniques'){const s=u.searchParams.get('show')||u.searchParams.get('group');return json(res,await liveEpisodes(s))}if(u.pathname==='/api/fullbooks'||u.pathname==='/api/chapters'){if(id){const b=books.find(x=>x.bookId===id);if(b&&local[id]?.length===b.count)return json(res,{...b,tracks:local[id]});const indexed=audioIndex.find(x=>x.bookId===id);if(indexed)return json(res,indexed);const known=archiveBooks.find(x=>x.bookId===id);if(known){try{return json(res,await archiveEdition(known))}catch{}}try{const arr=await librivox('',id,0);if(arr[0])return json(res,arr[0])}catch{}return json(res,{error:'Intégrale non vérifiée'},502)}const query=normal(q);const fixed=books.filter(b=>local[b.bookId]?.length===b.count&&normal(b.title+' '+b.author).includes(query));const stable=await archiveMatches(q,0);const indexed=audioIndex.filter(b=>normal(b.title+' '+b.author).includes(query));let remote=[];if(!audioIndex.length)try{remote=await librivox(q,null,offset)}catch{}const all=[...new Map([...indexed,...stable,...fixed,...remote].map(b=>[b.bookId,b])).values()];const items=audioIndex.length?all.slice(offset,offset+50):offset?remote:all;return json(res,{items,scanned:items.length,count:all.length,next:audioIndex.length?offset+50<all.length:remote.length>=50,indexed:audioIndex.length})}
if(u.pathname==='/api/archive-status'){return json(res,{references:idx.total,shows:idx.sources.map(x=>({id:x.id,title:rssMap.get(x.id)?.name||x.id,count:x.count,savedDelta:(delta[x.id]||[]).length,oldest:x.oldest,newest:x.newest,refreshConfigured:rssMap.has(x.id)}))})}
if(u.pathname==='/api/audio-status'){const show=u.searchParams.get('show');if(!idx.sources.some(x=>x.id===show))return json(res,{error:'Émission inconnue'},404);const rows=mergedEpisodes(episodes(show),delta[show]||[]);const target=rows.find(x=>x.id===id);if(!target)return json(res,{error:'Épisode absent des archives'},404);return json(res,{id:target.id,show,...await probeAudio(target.url)})}
if(u.pathname==='/api/reading'){let genre=u.searchParams.get('genre')||'Tous',page=Number(u.searchParams.get('page'))||1;return json(res,await readCatalogue(q,genre,Math.min(200,Math.max(1,page))))}
if(u.pathname==='/api/gallica')return json(res,await bdCatalogue(q,Math.min(200,Math.max(1,Number(u.searchParams.get('page'))||1))));
if(u.pathname==='/api/read'&&/^\d{1,7}$/.test(id||'')){const dir=id.slice(0,-1).split('').join('/')+'/'+id+'/';const sources=['https://gutenberg.pglaf.org/cache/epub/'+id+'/pg'+id+'.txt','https://www.gutenberg.org/cache/epub/'+id+'/pg'+id+'.txt',...['https://mirror.cs.odu.edu/gutenberg/','https://www.mirrorservice.org/sites/ftp.ibiblio.org/pub/docs/books/gutenberg/','https://gutenberg.pglaf.org/'].flatMap(host=>['-0.txt','.txt','-8.txt'].map(suffix=>host+dir+id+suffix))];const key='text:'+id;if(textCache.has(key))return json(res,textCache.get(key));try{const result=await Promise.any(sources.map(async url=>{const r=await fetch(url,{signal:AbortSignal.timeout(9000)});if(!r.ok)throw Error('HTTP');const bytes=await r.arrayBuffer();if(bytes.byteLength>12000000)throw Error('Too large');let t=new TextDecoder('utf-8').decode(bytes);if(t.includes('\ufffd'))t=new TextDecoder('windows-1252').decode(bytes);if(t.length<500||!/\*\*\*\s*START OF (?:THE|THIS) PROJECT GUTENBERG/i.test(t)||!/\*\*\*\s*END OF (?:THE|THIS) PROJECT GUTENBERG/i.test(t))throw Error('Incomplete text');return {text:t,complete:true,source:url}}));if(textCache.size>=12)textCache.delete(textCache.keys().next().value);textCache.set(key,result);return json(res,result)}catch{return json(res,{error:'Texte intégral momentanément indisponible sur les miroirs. Les livres déjà sauvegardés restent lisibles hors connexion.',source:'https://www.gutenberg.org/ebooks/'+id},502)}}
if(u.pathname==='/api/catalog'&&u.searchParams.get('kind')==='podcast')return json(res,await liveEpisodes(u.searchParams.get('feed')));
if(u.pathname==='/api/discovery'||u.pathname==='/api/hoopcast')return json(res,{items:[],shows:[],archived:true});
return json(res,{error:'Source non migrée'},503)}
function handler(req,res){Promise.resolve().then(async()=>{const u=new URL(req.url,'http://localhost');if(u.pathname==='/healthz')return json(res,{ok:true,references:idx.total,audioIndex:audioIndex.length,readingIndex:bulkItems.length,readingIndexSource:bulkSource,parts:idx.sources.reduce((n,s)=>n+s.parts.length,0)});if(u.pathname.startsWith('/api/'))return api(u,res);const relative=u.pathname==='/'?'index.html':decodeURIComponent(u.pathname.slice(1));const file=path.resolve(root,relative);if(!file.startsWith(root+path.sep)||!fs.existsSync(file)||!fs.statSync(file).isFile())return json(res,{error:'Not found'},404);res.writeHead(200,{'content-type':types[path.extname(file)]||'application/octet-stream','cache-control':'no-cache'});fs.createReadStream(file).pipe(res)}).catch(e=>{if(!res.headersSent)json(res,{error:'Source indisponible'},502);else res.end()})}

async function auditAllFeeds(){const ids=[...rssMap.keys()];let scanned=0,live=0,extra=0;for(let i=0;i<ids.length;i+=4){await Promise.allSettled(ids.slice(i,i+4).map(async id=>{const result=await liveEpisodes(id);scanned++;if(result.live)live++;const saved=mergedEpisodes(episodes(id),delta[id]||[]);const before=new Set(saved.map(x=>x.id));const fresh=result.items.filter(x=>!before.has(x.id));extra+=fresh.length;console.log('FEED_STATUS '+JSON.stringify({id,live:result.live,references:result.items.length,newReferences:fresh.length}));for(const item of fresh.slice(0,25))console.log('ARCHIVE_NEW '+JSON.stringify({show:id,item:{...item,desc:item.desc?.slice(0,200)}}))}))}console.log('FEED_AUDIT_ALL '+JSON.stringify({scanned,live,extra}))}

async function auditBatch(){const arg=process.argv[process.argv.indexOf('--audit-audio')+1];const start=Math.max(0,Math.floor(Number(process.argv[process.argv.indexOf('--audit-audio')+2])||0));const limit=Math.min(100,Math.max(1,Math.floor(Number(process.argv[process.argv.indexOf('--audit-audio')+3])||25)));let rows;if(arg==='hosted'){rows=audio.books.flatMap(b=>b.tracks.map((t,i)=>({id:b.id+':'+(i+1),title:t.title,url:t.url,kind:'hosted'})))}else if(arg==='books'){rows=Object.entries(local).flatMap(([id,tracks])=>tracks.map((t,i)=>({id:id+':'+(i+1),title:t.title,url:t.url,kind:'audio'})))}else{if(!idx.sources.some(x=>x.id===arg))throw Error('Usage: node server.cjs --audit-audio SHOW|books|hosted OFFSET LIMIT');rows=mergedEpisodes(episodes(arg),delta[arg]||[])}const subset=rows.slice(start,start+limit);let results=[];for(let i=0;i<subset.length;i+=3){const chunk=await Promise.all(subset.slice(i,i+3).map(async t=>({id:t.id,title:t.title,...await probeAudio(t.url)})));for(const item of chunk)console.log(JSON.stringify(item));results.push(...chunk);if(i+3<subset.length)await new Promise(resolve=>setTimeout(resolve,600))}console.log(JSON.stringify({audit:arg,total:rows.length,offset:start,checked:results.length,headerOk:results.filter(x=>x.state==='header_ok').length,next:start+results.length<rows.length?start+results.length:null,scope:'headers only; not full playback'}))}
if(process.argv.includes('--audit-audio')){auditBatch().catch(e=>{console.error(e.message);process.exitCode=1})}else if(process.argv.includes('--check')){let total=0;for(const s of idx.sources){const n=episodes(s.id).length;if(n!==s.count)throw Error(s.id+': '+n+' != '+s.count);total+=n;}if(total!==idx.total)throw Error('Archive count mismatch');console.log('Validated',total,'references',idx.sources.length,'shows',Object.keys(local).length,'local audiobooks');Promise.allSettled([bulkLoad(),buildAudioIndex(),auditArchive(),auditFeeds(),auditExpansion(),auditAllFeeds()]);}else http.createServer(handler).listen(Number(process.env.PORT)||10000,'0.0.0.0');